CREATE DATABASE IF NOT EXISTS ghflow;

CREATE TABLE IF NOT EXISTS ghflow.events (
    `id` Int64,
    `type` LowCardinality(String),
    `created_at` DateTime64(6, 'UTC'),
    `actor_id` Nullable(Int64),
    `actor_login` Nullable(String),
    `repo_id` Int64,
    `repo_name` Nullable(String),
    `org_id` Nullable(Int64),
    `org_login` Nullable(String),
    `public` Nullable(Bool),
    `action` Nullable(String),
    `push_id` Nullable(Int64),
    `ref` Nullable(String),
    `head_sha` Nullable(String),
    `before_sha` Nullable(String),
    `push_size` Nullable(Int64),
    `push_distinct_size` Nullable(Int64),
    `ref_type` Nullable(String),
    `full_ref` Nullable(String),
    `pr_number` Nullable(Int64),
    `pr_id` Nullable(Int64),
    `pr_merged` Nullable(Bool),
    `pr_additions` Nullable(Int64),
    `pr_deletions` Nullable(Int64),
    `pr_changed_files` Nullable(Int64),
    `issue_number` Nullable(Int64),
    `comment_id` Nullable(Int64),
    `review_state` Nullable(String),
    `release_tag` Nullable(String),
    `forkee_id` Nullable(Int64),
    `pages` Nullable(Int64),
    `hour` LowCardinality(String),
    `kafka_partition` UInt16,
    `kafka_offset` UInt64
)
ENGINE = ReplacingMergeTree
PARTITION BY toYYYYMM(created_at)
ORDER BY (toStartOfHour(created_at), id);

CREATE TABLE IF NOT EXISTS ghflow.hour_markers (
    `hour` LowCardinality(String),
    `partition` UInt16,
    `rows_in_hour` UInt64,
    `kafka_offset` UInt64
)
ENGINE = ReplacingMergeTree
ORDER BY (hour, partition);

CREATE TABLE IF NOT EXISTS ghflow.events_hourly (
    `hour_start` DateTime('UTC'),
    `type` LowCardinality(String),
    `ids` AggregateFunction(groupBitmap, UInt64)
)
ENGINE = AggregatingMergeTree
ORDER BY (hour_start, type);

CREATE TABLE IF NOT EXISTS ghflow.repo_current (
