CREATE MATERIALIZED VIEW IF NOT EXISTS ghflow.events_mv TO ghflow.events AS
SELECT assumeNotNull(`id`) AS `id`, assumeNotNull(`type`) AS `type`, assumeNotNull(`created_at`) AS `created_at`, `actor_id`, `actor_login`, assumeNotNull(`repo_id`) AS `repo_id`, `repo_name`, `org_id`, `org_login`, `public`, `action`, `push_id`, `ref`, `head_sha`, `before_sha`, `push_size`, `push_distinct_size`, `ref_type`, `full_ref`, `pr_number`, `pr_id`, `pr_merged`, `pr_additions`, `pr_deletions`, `pr_changed_files`, `issue_number`, `comment_id`, `review_state`, `release_tag`, `forkee_id`, `pages`, hour, _partition AS kafka_partition, _offset AS kafka_offset
FROM ghflow.events_queue WHERE kind = 'EVENT';

CREATE MATERIALIZED VIEW IF NOT EXISTS ghflow.hour_markers_mv TO ghflow.hour_markers AS
SELECT hour, assumeNotNull(partition) AS partition, assumeNotNull(rows_in_hour) AS rows_in_hour,
    _offset AS kafka_offset
FROM ghflow.events_queue WHERE kind = 'END_OF_HOUR';

CREATE MATERIALIZED VIEW IF NOT EXISTS ghflow.events_hourly_mv TO ghflow.events_hourly AS
SELECT toStartOfHour(assumeNotNull(created_at)) AS hour_start, assumeNotNull(type) AS type,
    groupBitmapState(toUInt64(assumeNotNull(id))) AS ids
FROM ghflow.events_queue WHERE kind = 'EVENT'
GROUP BY hour_start, type;

CREATE MATERIALIZED VIEW IF NOT EXISTS ghflow.repo_current_mv TO ghflow.repo_current AS
SELECT * FROM ghflow.repo_state_queue;

